mapper.select:
select t.id, t.assignee_sys_user_id as assigneeSysUserId, t.subject_type as subjectType, t.subject_id as subjectId, t.status, t.priority, t.due_at as dueAt, t.completed_at as completedAt, t.created_at as createdAt, t.updated_at as updatedAt, case when t.status != 'done' and t.due_at < now() then 1 else 0 end as overdue, su.user_name as assigneeUserName, su.nick_name as assigneeNickName, nz.value as noteZh from cm_staff_tasks t left join sys_user su on su.user_id = t.assignee_sys_user_id left join cm_staff_task_localized_fields nz on nz.staff_task_id = t.id and nz.field_name = 'note' and nz.locale = 'zh' where 1 = 1
and ( t.subject_id like concat('%', #{keyword}, '%') or nz.value like concat('%', #{keyword}, '%') or su.user_name like concat('%', #{keyword}, '%') or su.nick_name like concat('%', #{keyword}, '%') )
and t.subject_type = #{subjectType}
and t.status = #{status}
and t.priority = #{priority}
and t.assignee_sys_user_id = #{assigneeSysUserId}
order by case when t.status != 'done' and t.due_at < now() then 0 when t.status = 'done' then 2 else 1 end, t.due_at, t.updated_at desc, t.id desc

mapper.insert:
